async function manage_cognitive_workspace(params, userSettings, resources) {
  const { 
    action = 'update', 
    macro_goal, 
    active_subtask, 
    boundary_constraints = [], 
    active_hypothesis, 
    falsification_check, 
    branch_id = 'main', 
    parent_branch_id = null,
    branch_eval_score = 1.0,
    sync_to_workspace = true 
  } = params;

  let state = await storage.get('workspace_state') || {
    macro_goal: '',
    active_subtask: '',
    boundary_constraints: [],
    active_hypothesis: '',
    falsification_check: '',
    branches: {
      'main': { id: 'main', parent: null, hypothesis: '', status: 'active', score: 1.0, history: [] }
    },
    active_branch: 'main',
    updated_at: new Date().toISOString()
  };

  if (action === 'read') {
    return JSON.stringify({ status: 'success', current_workspace: state }, null, 2);
  }

  if (macro_goal) state.macro_goal = macro_goal;
  if (active_subtask) state.active_subtask = active_subtask;
  if (boundary_constraints && boundary_constraints.length > 0) state.boundary_constraints = boundary_constraints;
  if (active_hypothesis) state.active_hypothesis = active_hypothesis;
  if (falsification_check) state.falsification_check = falsification_check;

  if (action === 'fork_branch') {
    const newBranchId = branch_id || ('branch_' + Date.now());
    state.branches[newBranchId] = {
      id: newBranchId,
      parent: parent_branch_id || state.active_branch,
      hypothesis: active_hypothesis || '',
      status: 'exploring',
      score: branch_eval_score,
      created_at: new Date().toISOString()
    };
    state.active_branch = newBranchId;
  } else if (action === 'prune_branch') {
    if (state.branches[branch_id]) {
      state.branches[branch_id].status = 'pruned_dead_end';
      state.branches[branch_id].pruned_at = new Date().toISOString();
      if (state.active_branch === branch_id) {
        state.active_branch = state.branches[branch_id].parent || 'main';
      }
    }
  } else {
    if (!state.branches[branch_id]) {
      state.branches[branch_id] = { id: branch_id, parent: null, status: 'active', score: 1.0 };
    }
    state.branches[branch_id].hypothesis = active_hypothesis || state.branches[branch_id].hypothesis;
    state.branches[branch_id].score = branch_eval_score;
    state.active_branch = branch_id;
  }

  state.updated_at = new Date().toISOString();
  await storage.set('workspace_state', state);

  let workspaceFileNote = '';
  if (sync_to_workspace && workspace && workspace.saveData) {
    try {
      const fileRes = await workspace.saveData('cognitive_workspace', state, 'json');
      workspaceFileNote = ' Synchronized to ' + fileRes.relativePath + '.';
    } catch (e) {}
  }

  return JSON.stringify({
    status: 'success',
    message: 'Cognitive workspace updated successfully.' + workspaceFileNote,
    active_branch: state.active_branch,
    active_subtask: state.active_subtask,
    boundary_constraints: state.boundary_constraints,
    falsification_check: state.falsification_check
  }, null, 2);
}

async function manage_task_scheduler(params, userSettings, resources) {
  const { action = 'list', tasks = [], target_task_id, target_status, verification_proof } = params;
  let dag = await storage.get('task_dag') || [];

  if (action === 'create_plan') {
    dag = tasks.map((t, idx) => ({
      id: t.id || ('task_' + (idx + 1)),
      title: t.title,
      dependencies: t.dependencies || [],
      verification_criteria: t.verification_criteria || 'Explicit output verification',
      status: t.status || 'pending',
      verification_proof: null,
      updated_at: new Date().toISOString()
    }));
    await storage.set('task_dag', dag);
    if (workspace && workspace.saveData) {
      await workspace.saveData('task_scheduler_dag', dag, 'json');
    }
    return JSON.stringify({ status: 'success', message: 'Initialized task plan with ' + dag.length + ' tasks.', plan: dag }, null, 2);
  }

  if (action === 'update_task' || action === 'verify_task') {
    if (!target_task_id) throw new Error("Missing 'target_task_id' for update/verify action.");
    const taskIndex = dag.findIndex(t => t.id === target_task_id);
    if (taskIndex === -1) throw new Error("Task '" + target_task_id + "' not found in task scheduler.");

    if (action === 'verify_task') {
      if (!verification_proof) throw new Error("A task cannot be marked 'verified' without providing 'verification_proof'.");
      dag[taskIndex].status = 'verified';
      dag[taskIndex].verification_proof = verification_proof;
    } else {
      if (target_status) dag[taskIndex].status = target_status;
      if (verification_proof) dag[taskIndex].verification_proof = verification_proof;
    }
    dag[taskIndex].updated_at = new Date().toISOString();
    await storage.set('task_dag', dag);
    if (workspace && workspace.saveData) {
      await workspace.saveData('task_scheduler_dag', dag, 'json');
    }
    return JSON.stringify({ status: 'success', message: "Task '" + target_task_id + "' updated.", task: dag[taskIndex] }, null, 2);
  }

  return JSON.stringify({ status: 'success', total_tasks: dag.length, tasks: dag }, null, 2);
}

async function commit_evidence_node(params, userSettings, resources) {
  const {
    folder = 'general',
    topic = 'unfiled',
    claim,
    source_url,
    source_title = 'Web Source',
    credibility_tier = 'secondary',
    sift_weight = 0.5,
    verbatim_quote,
    confidence = 'Medium',
    tabular_data = null,
    stage_to_workspace = false
  } = params;

  if (!claim) throw new Error("Parameter 'claim' is required.");
  if (!verbatim_quote && credibility_tier !== 'tertiary') {
    throw new Error("Rigorous lineage mandate: You must provide a 'verbatim_quote' supporting this claim for primary/secondary sources.");
  }

  let tree = await storage.get('knowledge_tree') || {};
  if (!tree[folder]) tree[folder] = {};
  if (!tree[folder][topic]) tree[folder][topic] = [];

  const nodeId = 'ev_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6);
  const node = {
    id: nodeId,
    claim,
    source_url: source_url || 'direct_observation',
    source_title,
    credibility_tier,
    sift_weight: typeof sift_weight === 'number' ? sift_weight : 0.5,
    verbatim_quote: verbatim_quote || '',
    confidence,
    committed_at: new Date().toISOString()
  };

  tree[folder][topic].push(node);
  await storage.set('knowledge_tree', tree);

  let stagedPath = null;
  if (stage_to_workspace && workspace) {
    const slug = (folder + '_' + topic).replace(/[^a-z0-9_-]/gi, '_').toLowerCase();
    if (tabular_data) {
      const isCsv = String(tabular_data).trim().includes('\n') && String(tabular_data).includes(',');
      const fileRes = await workspace.writeFile('evidence_' + slug + (isCsv ? '.csv' : '.json'), String(tabular_data), 'in');
      stagedPath = fileRes.relativePath;
    } else {
      const fileRes = await workspace.saveData('evidence_' + slug, tree[folder][topic], 'json');
      stagedPath = fileRes.relativePath;
    }
  }

  return JSON.stringify({
    status: 'success',
    node_id: nodeId,
    location: folder + ' / ' + topic,
    staged_to_workspace: stagedPath,
    agent_note: stagedPath 
      ? 'Evidence staged at /workspace/' + stagedPath + '. You can use execute_python with pandas to inspect, audit, or model this data.'
      : 'Evidence committed to persistent knowledge tree under [' + folder + ' > ' + topic + '].'
  }, null, 2);
}

async function query_knowledge_base(params, userSettings, resources) {
  const { folder, topic, search_query, min_credibility = 'all', list_topics_only = false } = params;
  const tree = await storage.get('knowledge_tree') || {};

  if (list_topics_only) {
    const directory = {};
    for (const f of Object.keys(tree)) {
      directory[f] = Object.keys(tree[f]).map(t => ({
        topic: t,
        nodes_count: tree[f][t].length
      }));
    }
    return JSON.stringify({ status: 'success', directory }, null, 2);
  }

  let nodes = [];
  const foldersToSearch = folder ? (tree[folder] ? [folder] : []) : Object.keys(tree);

  for (const f of foldersToSearch) {
    const topicsToSearch = topic ? (tree[f][topic] ? [topic] : []) : Object.keys(tree[f] || {});
    for (const t of topicsToSearch) {
      const items = tree[f][t] || [];
      items.forEach(item => {
        nodes.push({ folder: f, topic: t, ...item });
      });
    }
  }

  if (min_credibility === 'primary_only') {
    nodes = nodes.filter(n => n.credibility_tier === 'primary' || n.sift_weight >= 0.75);
  } else if (min_credibility === 'secondary_and_above') {
    nodes = nodes.filter(n => n.credibility_tier !== 'tertiary');
  }

  if (search_query) {
    const qLower = String(search_query).toLowerCase();
    nodes = nodes.filter(n => 
      n.claim.toLowerCase().includes(qLower) || 
      (n.verbatim_quote && n.verbatim_quote.toLowerCase().includes(qLower)) ||
      n.topic.toLowerCase().includes(qLower)
    );
  }

  return JSON.stringify({
    status: 'success',
    matched_count: nodes.length,
    results: nodes.slice(0, 25)
  }, null, 2);
}

async function execute_backtrack_audit(params, userSettings, resources) {
  const {
    failed_step,
    error_coordinate,
    root_cause_analysis,
    counterfactual_rule,
    prune_branch_id,
    compile_permanent_sop = false
  } = params;

  if (!failed_step || !error_coordinate || !counterfactual_rule) {
    throw new Error("Missing required audit fields: failed_step, error_coordinate, and counterfactual_rule.");
  }

  const auditEntry = {
    id: 'audit_' + Date.now(),
    failed_step,
    error_coordinate,
    root_cause_analysis: root_cause_analysis || 'Unspecified decoupling of model reasoning from ground truth',
    counterfactual_rule,
    timestamp: new Date().toISOString()
  };

  let audits = await storage.get('episodic_audits') || [];
  audits.unshift(auditEntry);
  if (audits.length > 50) audits = audits.slice(0, 50);
  await storage.set('episodic_audits', audits);

  let branchPruned = null;
  if (prune_branch_id) {
    let workspaceState = await storage.get('workspace_state');
    if (workspaceState && workspaceState.branches && workspaceState.branches[prune_branch_id]) {
      workspaceState.branches[prune_branch_id].status = 'pruned_dead_end';
      workspaceState.branches[prune_branch_id].prune_reason = counterfactual_rule;
      if (workspaceState.active_branch === prune_branch_id) {
        workspaceState.active_branch = workspaceState.branches[prune_branch_id].parent || 'main';
      }
      await storage.set('workspace_state', workspaceState);
      branchPruned = prune_branch_id;
    }
  }

  let sopCompiled = null;
  if (compile_permanent_sop) {
    let policies = await storage.get('metacognitive_policies') || [];
    const newPolicy = {
      id: 'sop_' + Date.now(),
      rule: counterfactual_rule,
      trigger_condition: 'Evaluation of ' + failed_step,
      context: root_cause_analysis,
      compiled_at: new Date().toISOString()
    };
    policies.push(newPolicy);
    await storage.set('metacognitive_policies', policies);
    sopCompiled = newPolicy;
  }

  return JSON.stringify({
    status: 'success',
    message: 'Failure localized. Backtrack state locked in episodic memory.',
    audit: auditEntry,
    pruned_branch: branchPruned,
    sop_compiled: sopCompiled,
    recovery_directive: "Proceed with counterfactual alternative: '" + counterfactual_rule + "'. Do NOT repeat past failure coordinates."
  }, null, 2);
}

